mapper.select:
SELECT p.id, p.bill_no, p.sign_code, p.node_no, p.site_id, p.site_no, e.site_name, e.site_type, e.road_name, e.status AS site_status, p.should_count, p.done_count, p.lack_count, p.status, p.content, p.remark, p.create_time FROM t_salt_link_page p INNER JOIN t_salt_ent e ON e.id = p.site_id AND e.del_flag = 0 WHERE p.del_flag = 0 AND p.id = #{id}
AND e.road_name LIKE CONCAT(#{roadPrefix}, '%')
LIMIT 1
